 "oaepl214e0": "Voiture (Ackermann)",
 "vguyv6e8lg": "1 / 1 / 2",
 "1575b9nvyco": "stable à vitesse élevée, extérieur, bonne traction",
 "25zp1jmoz02": "rayon de virage minimal ; demande des manœuvres",
 "9odcqqfdfy": "Tricycle",
